/* Rythme conseillé : valeur par type, sauf exception par exercice. */
const TEMPO_T={poly:"2 s descente · 1 s pause · 1 s montée",iso:"1 s effort · 1 s serré · 2 s retour",gain:"Tenir 20 à 40 s · respirer",etir:"Tenir 30 s · souffler lentement",echa:"Lent et fluide · sans forcer"};
const POLY=new Set(["smsq","press","bulg","rdl","rdlx","sumosq","stepup","dch","incl","dbinc","benchx","pompes","pompesd","diam","pike","dips","dipsb","dipsbanc","tract","tvert","rowm","rowx","rowinv","rowu","rowc","tlarg","dmil","hack","gobsq","squatpdc","fentes"]);
